"""Parser for the supplier's stock feed (CSV, one row per SKU)."""
import csv
import io


def parse_feed(text):
    """Return stock quantities keyed by SKU.

    The supplier's current feed names its quantity column ``available``;
    accept the older ``qty`` name as a fallback for existing feed exports.
    """
    rows = csv.DictReader(io.StringIO(text))
    if rows.fieldnames is None:
        return {}

    quantity_column = "available" if "available" in rows.fieldnames else "qty"
    if "sku" not in rows.fieldnames or quantity_column not in rows.fieldnames:
        raise ValueError("feed must contain 'sku' and 'available' columns")

    return {row["sku"].strip(): int(row[quantity_column]) for row in rows}

