"""Parser for the supplier's stock feed (CSV, one row per SKU)."""
import csv
import io


def parse_feed(text):
    """Return stock quantities keyed by SKU.

    The supplier's current feed calls the quantity column ``available``;
    older exports used ``qty``. Accept both during the schema transition.
    """
    rows = csv.DictReader(io.StringIO(text))
    if not rows.fieldnames or "sku" not in rows.fieldnames:
        raise ValueError("stock feed must contain a 'sku' column")

    quantity_column = "available" if "available" in rows.fieldnames else "qty"
    if quantity_column not in rows.fieldnames:
        raise ValueError("stock feed must contain an 'available' or 'qty' column")

    return {
        row["sku"].strip(): int(row[quantity_column])
        for row in rows
    }

