from dataclasses import dataclass, field
from datetime import datetime
from decimal import ROUND_HALF_UP, Decimal

CENT = Decimal("0.01")


@dataclass
class Line:
    description: str
    unit_price: Decimal
    quantity: int = 1
    discount_pct: Decimal = Decimal("0")  # percentage points: 10 means 10%

    @property
    def total(self):
        gross = self.unit_price * self.quantity
        return (gross * (1 - self.discount_pct)).quantize(CENT, rounding=ROUND_HALF_UP)


@dataclass
class Invoice:
    customer: str
    lines: list = field(default_factory=list)
    number: str | None = None
    issued_at: datetime | None = None
    paid: bool = False
    id: int | None = None

    @property
    def total(self):
        return sum((line.total for line in self.lines), Decimal("0"))

    def issue(self, number):
        self.number = number
        self.issued_at = datetime.utcnow()


def format_number(seq, year):
    return f"INV-{year}-{seq:05d}"

CREATE SEQUENCE IF NOT EXISTS invoice_number_seq;

CREATE TABLE IF NOT EXISTS invoices (
    id          bigserial PRIMARY KEY,
    number      text UNIQUE,
    customer    text NOT NULL,
    issued_at   timestamptz,
    paid        boolean NOT NULL DEFAULT false
);

CREATE TABLE IF NOT EXISTS invoice_lines (
    id           bigserial PRIMARY KEY,
    invoice_id   bigint NOT NULL REFERENCES invoices (id),
    description  text NOT NULL,
    unit_price   numeric(12, 2) NOT NULL,
    quantity     integer NOT NULL DEFAULT 1,
    discount_pct numeric(5, 2) NOT NULL DEFAULT 0
);

